	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/members/{memberId}/weekly-plan", wrapper.GetMemberWeeklyPlan)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/members/{memberId}/journey", wrapper.GetMemberJourney)
